  if (typeof name !== "string" || name.startsWith(OFFICIAL_SCOPE)) return null;
  const short = shortPluginName(name);
  const hit = PLUGIN_TITLES[short] ?? PLUGIN_TITLES[short.toLowerCase()];
  if (hit !== undefined) return hit;
  return isEnglishOnly(short) ? composeBilingual(short) : null;
