function pinBilingualLabels() {
  if (typeof document === "undefined" || typeof MutationObserver === "undefined") return;
  const apply = () => {
    for (const listbox of Array.from(document.querySelectorAll('[role="listbox"]'))) pinCommandPopup(listbox);
    pinTabs();
    pinPluginCards();
  };
  apply();
  new MutationObserver(apply).observe(document.body, { childList: true, subtree: true });
}

